/**
 * generated by stackra gen from src/routes/<name>/<name>.route.ts (every route folder) — do not
 * edit
 * Purpose: every route by its key (the snake_case of its folder) as a `RouteRef`: layouts, menus,
 *          pages and data navigate with `Routes.<key>` (`navigate.to(Routes.order_detail, params)`,
 *          `ctx.redirect(Routes.sign_in)`, `m.route(Routes.order_detail)`), never with the route
 *          class; and `RouteKey`, the keys as an enum, for shapes whose data names a route.
 * Boundary: data plus types. The route classes are imported as types only, so importing this file
 *           never loads a route module and no layout, menu or page can close an import cycle
 *           through it (links point down: layout ← route → page). The key → class table the router
 *           mounts is `route-table.ts`, imported only by the generated entry and tree.
 * Runtime: isomorphic
 */
import { type InferParams, routeRef } from "@stackra/navigation";
