import type { AnnouncementsRoute } from "#src/routes/announcements/announcements.route";
import type { CreateOrderRoute } from "#src/routes/create-order/create-order.route";
import type { HomeRoute } from "#src/routes/home/home.route";
import type { InboxRoute } from "#src/routes/inbox/inbox.route";
import type { NotificationPreferencesRoute } from "#src/routes/notification-preferences/notification-preferences.route";
import type { OrderDetailRoute } from "#src/routes/order-detail/order-detail.route";
import type { OrdersRoute } from "#src/routes/orders/orders.route";
